export default function SkillLogo({ icon, size }: { icon: SkillIcon; size: number }) {
  const svg = { width: size, height: size, viewBox: "0 0 24 24", "aria-hidden": true } as const;

  switch (icon) {
    case "mysql":
      return (
        <svg {...svg}>
          <path d={MYSQL} fill="#4479A1" />
        </svg>
      );

    case "tailwind":
      return (
        <svg {...svg}>
          <path d={TAILWIND} fill="#06B6D4" />
        </svg>
      );

    case "githubcli":
      // Official GitHub mark, plus a separate terminal badge (the mark itself is not altered).
      return (
        <svg {...svg} viewBox="0 0 26 26">
          <path d={GITHUB} fill="#181717" />
          <rect x="13.5" y="15.5" width="11.5" height="9" rx="1.5" fill="#181717" stroke="#f5f0e1" strokeWidth="1.2" />
          <path d="M15.6 18.2l2 1.5-2 1.5M18.9 22.3h3.6" fill="none" stroke="#f5f0e1" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      );

    case "sql":
      // Conventional database symbol (SQL has no official logo).
      return (
        <svg {...svg}>
          <path d="M3.5 5.2C3.5 3.4 7.3 2 12 2s8.5 1.4 8.5 3.2v13.6C20.5 20.6 16.7 22 12 22s-8.5-1.4-8.5-3.2Z" fill="#0F6CBD" />
          <ellipse cx="12" cy="5.2" rx="8.5" ry="3.2" fill="#3D8FE0" />
          <path d="M3.5 9.6c0 1.8 3.8 3.2 8.5 3.2s8.5-1.4 8.5-3.2" fill="none" stroke="#9CC6F2" strokeWidth="1" />
          <text x="12" y="19" textAnchor="middle" fontSize="5.6" fontWeight="900" fill="#ffffff" fontFamily="Arial, Helvetica, sans-serif">
            SQL
          </text>
        </svg>
      );

    case "api":
      // Conventional API symbol: braces with request/response arrows (REST has no official logo).
      return (
        <svg {...svg}>
          <rect x="1.5" y="1.5" width="21" height="21" rx="4" fill="#FF7A2F" />
          <path
            d="M8 6.5c-1.6 0-2 .8-2 2v1.6c0 .8-.4 1.5-1.4 1.9 1 .4 1.4 1.1 1.4 1.9v1.6c0 1.2.4 2 2 2M16 6.5c1.6 0 2 .8 2 2v1.6c0 .8.4 1.5 1.4 1.9-1 .4-1.4 1.1-1.4 1.9v1.6c0 1.2-.4 2-2 2"
            fill="none"
            stroke="#ffffff"
            strokeWidth="1.6"
            strokeLinecap="round"
          />
          <path d="M9.5 10.3h5l-1.6-1.5M14.5 13.7h-5l1.6 1.5" fill="none" stroke="#ffffff" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      );
  }
}
